{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table snitch_db.maplemonk.sku_live_mech_v2 as WITH data AS ( SELECT sku_group, SUM( CASE WHEN transfer_branch_code != 32 THEN total_qty ELSE NULL END ) AS ordered, SUM( CASE WHEN transfer_branch_code = 8 THEN total_qty ELSE NULL END ) AS south, SUM( CASE WHEN transfer_branch_code = 94 THEN total_qty ELSE NULL END ) AS north FROM SNITCH_DB.MAPLEMONK.LOGIC_PURCHASE_ORDER GROUP BY 1 ), puta AS ( SELECT UPPER( TRIM( REGEXP_REPLACE(\"Item Type skuCode\"::STRING, \'-[^-]+$\', \'\') ) ) AS sku_group, SUM( CASE WHEN \"Warehouse Name\" = \'SAPL-WH2\' THEN putaway_completed_quantity ELSE NULL END ) AS south, SUM( CASE WHEN \"Warehouse Name\" = \'SAPL-NORTH-TAURU\' THEN putaway_completed_quantity ELSE NULL END ) AS north, SUM( CASE WHEN \"Warehouse Name\" IN (\'SAPL-NORTH-TAURU\', \'SAPL-WH2\') THEN putaway_completed_quantity ELSE NULL END ) AS inwarded, MAX( CASE WHEN \"Warehouse Name\" = \'SAPL-WH2\' THEN putaway_updated::date ELSE NULL END ) AS south_inwarded_date, MAX( CASE WHEN \"Warehouse Name\" = \'SAPL-NORTH-TAURU\' THEN putaway_updated::date ELSE NULL END ) AS north_inwarded_date, MAX( CASE WHEN \"Warehouse Name\" IN (\'SAPL-NORTH-TAURU\', \'SAPL-WH2\') THEN putaway_updated::date ELSE NULL END ) AS inwarded_date FROM snitch_db.maplemonk.putaway_tracking WHERE final_type = \'New Inward\' GROUP BY 1 ), final AS ( SELECT sku_group, d.ordered, d.south South_PO, d.north North_PO, p.inwarded, p.south south_inwarded, p.north North_inwarded, p.north_inwarded_date north_inwarded_date, p.south_inwarded_date south_inwarded_date, p.inwarded_date inwarded_date, b.final_live_date, (p.inwarded / NULLIF(d.ordered, 0)) inwarded_prec, ( CASE WHEN d.south > 0 THEN 1 ELSE 0 END ) + ( CASE WHEN d.north > 0 THEN 1 ELSE 0 END ) AS PO_raised_WH_count, ( CASE WHEN p.south > 0 THEN 1 ELSE 0 END ) + ( CASE WHEN p.north > 0 THEN 1 ELSE 0 END ) AS inwarded_WH_count, CASE WHEN c.sku_group IS NULL THEN \'No Offline Allocation\' ELSE \'Offline Allocated\' END Offline_Allocated_Status FROM data d LEFT JOIN puta p USING (sku_group) LEFT JOIN snitch_db.maplemonk.product_journey b USING (sku_group) LEFT JOIN ( SELECT DISTINCT REGEXP_REPLACE(sku, \'-[^-]+$\', \'\') AS sku_group FROM snitch_db.maplemonk.b2b_journey ) c USING (sku_group) WHERE sku_group NOT IN ( SELECT DISTINCT sku_group FROM snitch_db.maplemonk.horizontal_sales_categories WHERE sku_group IS NOT NULL and type =\'Shopify\' ) AND ordered >= 100 ), live_check as ( select distinct sku_group, live_date from snitch_db.maplemonk.category_journey ) SELECT distinct f.sku_group, f.ordered, f.South_PO, f.North_PO, f.inwarded, f.south_inwarded, f.North_inwarded, f.PO_raised_WH_count, f.inwarded_WH_count, ROUND(100 * f.inwarded_prec, 1) AS inwarded_prec, CASE WHEN f.inwarded_prec >= 0.9 THEN f.inwarded_date END AS WH_Live_date, cj.image_url AS SKU_image, CASE WHEN f.sku_group LIKE \'MP%\' THEN \'Marketplace Specific SKU\' WHEN f.inwarded_prec >= 0.9 THEN \'Ready to go live\' WHEN f.PO_raised_WH_count <= f.inwarded_WH_count THEN \'Ready to go live\' ELSE \'Not Ready to go Live\' END AS Remarks, f.Offline_Allocated_Status, CASE WHEN f.sku_group NOT LIKE \'MP%\' THEN CASE WHEN f.inwarded_prec >= 0.9 AND f.final_live_date IS NULL THEN \'Make it Live in Online\' WHEN f.inwarded_prec < 0.9 AND f.final_live_date IS NOT NULL THEN \'Should not have made Live\' WHEN f.inwarded_prec >= 0.9 AND f.final_live_date IS NOT NULL THEN \'Already Live in Online\' WHEN f.PO_Raised_WH_COUNT <= INWARDED_WH_COUNT THEN \'Ready to go live\' ELSE \'Do not Make Live\' END END AS Online_Remarks, CASE WHEN f.sku_group NOT LIKE \'MP%\' THEN CASE WHEN f.inwarded_prec >= 0.9 AND f.Offline_Allocated_Status = \'No Offline Allocation\' THEN \'Make Allocation in Offline\' WHEN f.inwarded_prec < 0.9 AND f.Offline_Allocated_Status = \'Offline Allocated\' THEN \'Should not have made Allocations\' WHEN f.inwarded_prec >= 0.9 AND f.Offline_Allocated_Status = \'Offline Allocated\' THEN \'Offline Allocation Already Done\' ELSE \'Do not Make Allocations\' END END AS Offline_Remarks, lf.live_date FROM final f LEFT JOIN snitch_db.maplemonk.category_journey cj ON cj.sku_group = f.sku_group left join live_check lf on f.sku_group = lf.sku_group where lf.live_date > \'2026-01-01\' or lf.live_date is null;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from snitch_db.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            